function leadForm(interest){modal('Interesse / demonstração local.','<p class="help">O formulário adiciona um interesse ao CRM deste navegador. Nada é enviado à equipe; use dados fictícios.</p><form id="lead-form"><label>Nome fictício<input name="name" required minlength="3" maxlength="100"></label><label>E-mail fictício<input name="email" type="email" required maxlength="200"></label><label>Interesse<select name="interest"><option value="annual" '+(interest==='annual'?'selected':'')+'>Plano anual</option><option value="custom" '+(interest==='custom'?'selected':'')+'>Projeto personalizado</option></select></label><label>Contexto fictício<textarea name="message" rows="3" maxlength="1000"></textarea></label><label class="checkbox mt"><input type="checkbox" required name="demoConsent">Entendo que este registro é local e demonstrativo, sem contato real.</label><button class="btn gold full mt">Registrar interesse na demo</button></form>');}
