const seed=()=>({profile:{name:'Marina Duarte',email:'marina@exemplo.com',stage:'active',introSeen:false,assessmentDone:true,answers:{goal:'Hipertrofia',days:'3'},joined:false},optIn:false,session:null,completed:[],measurements:[{date:'2026-09-02',weight:70,waist:80},{date:'2026-09-09',weight:69.8,waist:79.5},{date:'2026-09-16',weight:69.4,waist:79},{date:'2026-09-23',weight:69.2,waist:78.7},{date:'2026-09-30',weight:69,waist:78.5}],clients:[{id:'demo-marina',name:'Marina Duarte',email:'marina@exemplo.com',stage:'active',owner:'Bruno',next:'Revisar execução e adaptar o próximo ciclo',due:'A definir',last:'Há 2 dias',plan:'base-a',consent:false,timeline:[{at:'Dados de exemplo',title:'Plano demonstrativo disponível',text:'Exemplo sem personalização ou IA real.'}],notes:[]},{id:'demo-lucas',name:'Lucas Costa',email:'lucas@exemplo.com',stage:'onboarding',owner:'Bruno',next:'Orientar a conclusão da anamnese',due:'A definir',last:'Há 5 dias',plan:'',consent:false,timeline:[{at:'Dados de exemplo',title:'Acesso demonstrativo criado',text:'Convite real não foi enviado.'}],notes:[]},{id:'demo-julia',name:'Julia Lima',email:'julia@exemplo.com',stage:'renewal',owner:'Atendimento',next:'Ouvir feedback sobre o ciclo',due:'A definir',last:'Há 1 dia',plan:'base-b',consent:false,timeline:[],notes:[]},{id:'demo-pedro',name:'Pedro Almeida',email:'pedro@exemplo.com',stage:'purchase',owner:'Atendimento',next:'Confirmar interesse e esclarecer a proposta',due:'A definir',last:'Hoje',plan:'',consent:false,timeline:[],notes:[]}],tasks:[{id:'task-1',client:'demo-lucas',title:'Ajudar a concluir a anamnese',owner:'Bruno',due:'A definir',done:false},{id:'task-2',client:'demo-julia',title:'Revisar feedback antes da renovação',owner:'Atendimento',due:'A definir',done:false}],audit:[],operations:{},bindings:{},review:{training:'draft',nutrition:'pending'},chatMessages:[]});
let state;try{state=JSON.parse(localStorage.getItem('sim-prototype-v1'))||seed();}catch{state=seed();}
state.nutrition ||= {status:'draft',version:1,kcal:2100,reviewer:'Sanches | Nutrição & Bodybuilder Coach',civilName:'',crn:'',method:'A definir pelo nutricionista',portion:'Porções a definir pelo nutricionista',selected:{},restrictions:'unknown',preferences:'',history:[]};
state.studentReports ||= [];
let catalog=[],view='today',teamView='overview',selectedClient=state.clients[0].id,workoutIndex=0,exerciseIndex=0,joinStep=state.profile.joinStep||0,timerEnd=0,prepared=null,focusBeforeModal;
const labels={purchase:'Compra / interesse',onboarding:'Onboarding',active:'Ativos',renewal:'Renovação'};
